```javascript
// Portfolio valuation with precision
class PortfolioCalculator {
  calculateNetAssetValue(holdings, prices) {
    // Use decimal.js for financial precision
    let totalValue = new Decimal(0);

    for (const holding of holdings) {
      const price = prices[holding.symbol];
      const value = new Decimal(holding.quantity)
        .times(price.current)
        .times(holding.exchangeRate);

      totalValue = totalValue.plus(value);

      // Track for audit
      this.auditTrail.push({
        symbol: holding.symbol,
        quantity: holding.quantity,
        price: price.current,
        value: value.toFixed(2),
        timestamp: new Date()
      });
    }

    return {
      nav: totalValue.toFixed(2),
      auditTrail: this.auditTrail,
      calculated: new Date()
    };
  }
}
