### Compliance Reporting

```sql
-- Automated compliance report generation
CREATE OR REPLACE FUNCTION generate_compliance_report(
  start_date DATE,
  end_date DATE
) RETURNS TABLE (
  transaction_id UUID,
  client_id UUID,
  transaction_type VARCHAR,
  amount DECIMAL(15,2),
  status VARCHAR,
  compliance_flags TEXT[],
  created_at TIMESTAMPTZ
) AS $$
BEGIN
  RETURN QUERY
  SELECT 
    t.id,
    t.client_id,
    t.type,
    t.amount,
    t.status,
    ARRAY_AGG(DISTINCT cf.flag) as compliance_flags,
    t.created_at
  FROM transactions t
  LEFT JOIN compliance_flags cf ON t.id = cf.transaction_id
  WHERE t.created_at BETWEEN start_date AND end_date
  GROUP BY t.id
  ORDER BY t.created_at DESC;
END;
$$ LANGUAGE plpgsql;
```

