  setupCommunication() {
    // Cross-component messaging
    this.eventBus = new EventTarget();

    // Proxy for component isolation
    return new Proxy(this.eventBus, {
      get(target, prop) {
        if (prop === 'emit') {
          return (event, data) => {
            target.dispatchEvent(
              new CustomEvent(event, { detail: data })
            );
          };
        }
        return target[prop];
      }
    });
  }
}
